; === l_transform_byte: XOR over i of L_VEC[i]*src[i], returns byte in eax ===
; rdi=src r8=L_table
_l_transform_byte:
    movdqu xmm0,[rdi]
    vpshufb xmm0,xmm0,[r8]
    movd eax,xmm0
    mov esi,eax
    shr eax,16
    xor esi,eax
    shr eax,16
    xor esi,eax
    shr eax,16
    xor esi,eax
    ret

; === R_transform: cyclic right shift + l ===
; rdi=block(in/out) r8=L_table
R_transform:
    push rbp; mov rbp,rsp; sub rsp,40
    movdqu xmm0,[rdi]; movdqu [rsp+8],xmm0
    lea rdi,[rsp+8]; call _l_transform_byte
    lea rdi,[rsp+9]; mov rsi,rsp+8; mov r10d,15; rep movsb
    mov [rsp+8],al
    movdqu xmm0,[rsp+8]; movdqu [rdi],xmm0
    add rsp,40; pop rbp; ret

; === R_inv_transform: shift left + l ===
; rdi=block(in/out) r8=InvL_table
R_inv_transform:
    push rbp; mov rbp,rsp; sub rsp,40
    movdqu xmm0,[rdi]; movdqu [rsp+8],xmm0
    lea rdi,[rsp+9]; mov rsi,rsp+8; mov r10d,15; rep movsb
    mov al,[rsp+8]; mov [rsp+23],al
    lea rdi,[rsp+8]; call _l_transform_byte
    lea rdi,[rsp+8]; mov rsi,rsp+9; mov r10d,15; rep movsb
    mov [rsp+23],al
    movdqu xmm0,[rsp+8]; movdqu [rdi],xmm0
    add rsp,40; pop rbp; ret

; === L_transform: 16 iterations of R ===
; rdi=block(in/out) r8=L_table
kuznyechik_L_avx2:
    push rbp; mov rbp,rsp; mov r10,rdi
    mov ecx,16
L_loop:
    mov rdi,r10; call R_transform
    dec ecx; jnz L_loop
    pop rbp; ret

; === L_inv_transform: 16 iterations of R_inv ===
; rdi=block(in/out) r8=InvL_table
kuznyechik_L_inv_avx2:
    push rbp; mov rbp,rsp; mov r10,rdi
    mov ecx,16
L_inv_loop:
    mov rdi,r10; call R_inv_transform
    dec ecx; jnz L_inv_loop
    pop rbp; ret

; === set_key: rdi=key(32) rsi=expanded_key(160) ===
kuznyechik_set_key:
    push rbp; mov rbp,rsp
    sub rsp,64
    ; Load K0, K1
    movdqu xmm0,[rdi]; movdqu [rsp+16],xmm0
    movdqu xmm1,[rdi+16]; movdqu [rsp+32],xmm1
    ; Store initial K0, K1
    movdqu xmm0,[rsp+16]; movdqu [rsi],xmm0
    movdqu xmm1,[rsp+32]; movdqu [rsi+16],xmm1; add rsi,32
    mov r10d,0
key_groups:
    cmp r10d,4; jge key_done
    mov ecx,1
key_rounds:
    cmp ecx,9; jge key_store
    ; round_num = g*8 + j
    mov r11d,ecx; imul r11d,r11d,8; add r11d,r10d; mov r12d,r11d
    mov r12d,r12d; lea rbx,[rel round_constants]; movzx eax,byte [rbx+r12d]
    xorps xmm2,xmm2; movd xmm2,eax
    ; F_round: tmp = S(K0^C), L(tmp), tmp^=K1, swap K0,K1
    movdqu xmm3,[rsp+16]; pxor xmm3,xmm2
    lea rdx,[rel S_box_table]; vpshufb xmm3,xmm3,[rdx]
    movdqu [rsp+48],xmm3; mov rdi,rsp+48; call kuznyechik_L_avx2
    movdqu xmm4,[rsp+48]; pxor xmm4,[rsp+32]
    movdqu xmm3,[rsp+32]; movdqu [rsp+16],xmm3
    movdqu xmm3,xmm4; movdqu [rsp+32],xmm3
    inc ecx; jmp key_rounds
key_store:
    movdqu xmm0,[rsp+16]; movdqu [rsi],xmm0
    movdqu xmm1,[rsp+32]; movdqu [rsi+16],xmm1; add rsi,32
    inc r10d; jmp key_groups
key_done:
    add rsp,64; pop rbp; ret

; === encrypt_block: rdi=block(in/out) rsi=expanded_key(160) ===
kuznyechik_encrypt_block:
    push rbp; mov rbp,rsp
    mov r10,rdi; mov r11,rsi; mov ecx,9
enc_loop:
    movdqu xmm0,[r10]; movdqu xmm1,[r11]; pxor xmm0,xmm1
    lea rdx,[rel S_box_table]; vpshufb xmm0,xmm0,[rdx]
    movdqu [r10],xmm0; mov rdi,r10; call kuznyechik_L_avx2
    add r11,16; dec ecx; jnz enc_loop
    movdqu xmm0,[r10]; movdqu xmm1,[r11]; pxor xmm0,xmm1
    movdqu [r10],xmm0; pop rbp; ret

; === decrypt_block: rdi=block(in/out) rsi=expanded_key(160) ===
kuznyechik_decrypt_block:
    push rbp; mov rbp,rsp
    mov r10,rdi; mov r11,rsi; add r11,144; mov ecx,9
dec_loop:
    movdqu xmm0,[r10]; pxor xmm0,[r11]; movdqu [r10],xmm0
    mov rdi,r10; call kuznyechik_L_inv_avx2
    lea rdx,[rel InvS_box_table]
    movdqu xmm0,[r10]; vpshufb xmm0,xmm0,[rdx]; movdqu [r10],xmm0
    sub r11,16; dec ecx; jnz dec_loop
    mov r11,rsi
    movdqu xmm0,[r10]; pxor xmm0,[r11]; movdqu [r10],xmm0
    pop rbp; ret

; === encrypt_ecb: rdi=in rsi=out rdx=len rcx=expanded_key ===
kuznyechik_encrypt_ecb:
    push rbp; mov rbp,rsp
    mov r10,rdi; mov r11,rsi; mov r12,rdx; mov r13d,0
    mov r14,rcx
ecb_loop:
    cmp r13d,r12d; jge ecb_done
    mov rdi,r10; mov rsi,r14; call kuznyechik_encrypt_block
    add r10,16; add r11,16; add r13d,16
    jmp ecb_loop
ecb_done:
    pop rbp; ret

; === encrypt_ctr: rdi=in rsi=out rdx=len rcx=expanded_key r8=nonce ===
kuznyechik_encrypt_ctr:
    push rbp; mov rbp,rsp; sub rsp,48
    mov r10,rdi; mov r11,rsi; mov r12d,rdx; mov r13,rcx; mov r14,r8
    mov r15d,0
    ; Compute expanded key on stack
    mov rdi,r14; lea rsi,[rsp+16]; call kuznyechik_set_key
ctr_loop:
    cmp r15d,r12d; jge ctr_done
    ; Load nonce, increment counter
    movdqu xmm0,[r14]
    mov eax,[rsp+16]; add eax,r15d; mov [rsp+16],eax
    movdqu [rsp+8],xmm0
    ; Encrypt counter block
    mov rdi,[rsp+8]; mov rsi,[rsp+16]; call kuznyechik_encrypt_block
    ; XOR with data
    movdqu xmm0,[r10]; movdqu xmm1,[rsp+8]; pxor xmm0,xmm1
    movdqu [r10],xmm0
    add r10,16; add r11,16; add r15d,16
    jmp ctr_loop
ctr_done:
    add rsp,48; pop rbp; ret

